fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"
    val oneSecondNs = 1_000_000_000L
    if (exposureTimeNs >= oneSecondNs) {
        val seconds = exposureTimeNs / 1_000_000_000.0
        return if (seconds == seconds.toLong().toDouble()) "%ds".format(seconds.toLong()) else "%.2fs".format(seconds)
    }
    val denominator = (oneSecondNs.toDouble() / exposureTimeNs).roundToInt()
    return "1/${denominator}s"
}

